from model import *
c=C(14,'故障管理与预设模块详细设计','第二篇  分模块详细设计')
S(c,'故障目录与呈现结构',
P('故障定义与活动集合','''故障模块从 FailuresOrchestratorProvider 取得全部故障定义和当前活动故障集合。定义包含标识、名称和 ATA 章节，活动集合仅保存故障标识。目录内容与运行状态分离，因此同一目录可以用不同布局显示而不复制状态。

Provider 创建一次编排器，并在更新循环中调用 update。它取得新的活动集合后逐项比较，仅在集合内容变化时更新 React 状态，减少每个周期都重新渲染整张故障表。

目录存在表示软件认识该故障身份，不代表相关飞机系统都实现了完整故障传播。原生页面本身也保留这一能力说明，本书沿用该边界。''',diagram=D('entity','故障目录与运行集合',[['Failure 定义','identifier','name','ata'],['编排器','getAllFailures','getActiveFailures','activate / deactivate'],['页面状态','搜索条件','ATA 分组','活动标识集合']],[(0,1,'配置输入'),(1,2,'状态与动作接口')]),table=T('对象|变化频率|使用方式','故障定义|随机型配置更新|构造列表\n活动集合|随运行变化|决定活动样式\n搜索条件|随用户输入|过滤目录\n布局选择|随页面操作|切换显示形式')),
P('ATA 分组与搜索规则','''Failures 从全部故障定义中提取 ATA 编号，去重后按数值排序。搜索词转为大写，再同时匹配名称、标识文本和 ATA 章节标题。章节列表也根据过滤后的故障集合收缩。

这样用户可以从系统分类进入，也可以直接搜索故障名称或编号。搜索只影响可见范围，不会停止、激活或移除当前故障；某个活动故障因筛选而暂时不可见，并不意味着已经解除。

Comfort 布局强调章节浏览，Compact 布局强调同屏列表密度。两者使用相同 filteredFailures，状态来源一致，避免切换布局后出现两套不同故障记录。''',diagram=D('pipeline','故障目录的筛选过程',['全部定义','搜索词转大写','名称 / 编号 / 章节匹配','过滤故障集合','提取相关章节','Comfort 或 Compact']),table=T('搜索方式|匹配对象|适合情形','名称片段|failure.name|已知系统或部件\n编号|identifier 文本|已知故障标识\nATA 名称|章节标题|按专业系统定位\n空搜索词|全部故障|浏览完整目录')),
P('活动状态的视觉表达','''FailureButton 通过 isActive 选择红色或绿色边框，保留故障名称和可点击区域。搜索词可以在名称中强调显示，使用户知道该项为何被找到。活动状态应由编排器回读，而不是用户按下后永久保留一个页面本地布尔值。

这种单一状态来源使故障在其他入口被解除后，当前列表也能更新。Set 比较检查长度和成员关系，不依赖集合对象引用是否相同，因此同内容的新集合不会制造无意义渲染。

对于异步命令，更完善的界面还应表达请求中和失败。当前按钮的主要属性只有活动状态，本书不将它描述为已有完整命令回执面板。''',diagram=D('sequence','活动集合驱动按钮显示',['更新循环','编排器','Provider 状态','FailureButton'],[(0,1,'update'),(1,2,'取得活动集合'),(2,2,'比较大小与成员'),(2,3,'变化时传入 isActive')]),table=T('信息|当前显示载体|含义','故障名称|按钮正文|对象身份\n活动状态|边框样式|编排器报告状态\n搜索命中|强调文字|检索关系\n完整系统效应|不由按钮证明|依赖仿真后端')) ,refs=['EFB','FAIL'])
S(c,'故障命令与状态协调',
P('异步激活和解除接口','''Context 暴露 activate(identifier) 与 deactivate(identifier)，返回 Promise<void>。页面通过标识请求动作，Provider 转发给同一个编排器，不需要知道底层故障变量如何编码。

Promise 形式允许接口处理异步过程，但函数返回类型没有单独的业务回执对象。调用方不能仅凭拥有 Promise 就推断存在 accepted、running、completed 三阶段协议。活动集合仍是页面实际显示的状态来源。

浏览器宿主没有完整机载系统故障模型。激活动作的界面可见性和后台真实故障效应，应作为不同层面的能力理解。''',diagram=D('sequence','故障页面通过编排器发送命令',['故障按钮','Context 接口','FailuresOrchestrator','状态更新循环'],[(0,1,'identifier'),(1,2,'activate 或 deactivate'),(2,1,'异步完成或错误'),(3,2,'读取活动集合'),(3,0,'刷新活动显示')]),table=T('接口|参数|职责','activate|故障 identifier|请求激活\ndeactivate|故障 identifier|请求解除\ngetActiveFailures|无页面筛选参数|提供真实活动集合\ngetAllFailures|配置目录|提供可识别对象')),
P('页面筛选与故障身份稳定性','''故障动作必须使用稳定 identifier，不能使用当前列表的行号。搜索、ATA 分组和布局切换都会改变行序，而标识代表同一个故障定义。把行号当作故障编号会在筛选后操作错误对象。

名称承担可读性，ATA 承担分类，identifier 承担机器身份。机型更新可能调整名称和分类，但迁移运行记录时仍需要明确检查标识是否继续兼容，不能只按相似文字匹配。

外部仿真连接若有自己的故障枚举，应在适配层建立显式映射。映射缺失时应表达不支持，而不是向另一个系统发送碰巧相同的整数。''',diagram=D('entity','故障身份与外部映射的设计关系',[['页面目录','identifier','name','ATA'],['适配映射','本地 identifier','外部故障类型','支持状态'],['外部系统','模型故障身份','执行状态','作用范围']],[(0,1,'稳定身份'),(1,2,'明确映射')]),table=T('信息|稳定性用途|不宜代替身份','identifier|接口与状态关联|当前列表行号\nname|用户阅读与搜索|翻译后的相似文本\nATA|分类浏览|唯一故障身份\n外部枚举|后端协议|未经映射的本地整数')),
P('故障管理的扩展接口','''真实后端连接可把故障命令封装为带 commandId 和目标故障身份的请求，服务端回执记录接受或拒绝原因，活动快照记录 revision。页面据此区分点击已提交、故障已活动和执行失败。

解除故障也应作为明确请求处理，不能在网络断开时只把页面颜色恢复正常。若后台仍保留故障，重新连接后快照应重新显示其活动状态，使界面以实际运行状态为准。

该扩展设计没有改动 PBNVDT 故障接口。当前交付保留 Headwind 编排器与浏览器适配，后续连接需依据真实可用协议实现。''',diagram=D('state','扩展设计：故障命令和反馈状态',['未活动','激活请求中','已活动','解除请求中','请求失败'],[(0,1,'激活请求'),(1,2,'后台确认活动'),(2,3,'解除请求'),(3,0,'后台确认解除'),(1,4,'拒绝或超时'),(4,0,'重新读取状态')]),table=T('机制|解决的问题|当前性质','commandId|关联请求和回执|扩展设计\nrevision|识别新旧快照|扩展设计\n拒绝原因|解释动作失败|扩展设计\n活动集合回读|避免仅靠按钮推断|当前已有结构')) ,refs=['EFB','L-H','FAIL'])
S(c,'飞机与灯光预设',
P('飞机预设的前后台协议','''AircraftPresets 只发送预设加载请求，实际程序由后端 WASM 模块处理。L:A32NX_AIRCRAFT_PRESET_LOAD 大于零表示正在应用某个预设，完成后由后台清零；前端主动清零则表示取消。另有 EXPEDITE 变量控制是否跳过步骤间延时。

预设编号与后台程序定义保持一致，分别对应冷舱断电、已供电、准备推出、准备滑行和准备起飞。编号是协议值，不能随界面排序任意改变。

页面要求飞机在地面，并在用户选择预设后显示确认框。这个原生确认有实际意义，因为完整运行环境中预设会批量改变系统状态。''',diagram=D('sequence','飞机预设加载协议',['预设页面','LOAD 变量','WASM 程序','进度回调'],[(0,1,'写入预设编号'),(1,2,'后台开始应用'),(2,3,'进度及步骤文字'),(3,0,'更新进度条'),(2,1,'完成时清零')]),table=T('编号|预设|请求性质','1|Cold & Dark|整机状态程序\n2|Powered|供电状态程序\n3|Ready Pushback|推出准备程序\n4|Ready Taxi|滑行准备程序\n5|Ready Takeoff|起飞准备程序')),
P('进度、取消与加速选项','''AIRCRAFT_PRESET_WASM_CALLBACK 用分号分隔进度数值和步骤描述。前端解析数值后按百分比绘制进度条，同时显示当前步骤。加载变量变化时重置前端进度，使新的加载不沿用旧进度。

取消将 LOAD 写为零，表示后台停止继续应用。它不是自动撤销已经执行的步骤，也不把飞机恢复到请求前的完整状态。把取消描述成“回滚”会超出协议实际含义。

加速选项跳过程序步骤间延时，不改变预设身份。浏览器中没有运行该 WASM 后端，因此不能期待仅打开页面就得到真实飞机状态完成回执。''',diagram=D('lanes','加载、进度和取消的职责',[['请求','预设编号','LOAD > 0','后台执行'],['反馈','进度数值','步骤描述','前端显示'],['取消','用户取消','LOAD = 0','停止后续应用']]),table=T('动作|协议含义|不能推导的含义','取消|停止继续应用|恢复所有旧状态\n加速|跳过步骤间延时|跳过所有状态检查\n进度为 100%|后台报告进度|浏览器自己完成系统仿真')),
P('灯光预设名称与编号','''LightPresets 提供八个编号槽位，前端维护编号到名称的 Map，后台按编号存取实际灯光状态。LIGHT_PRESET_NAMES 只保存命名信息，不承载全部灯光通道数值。

Map 不能直接按普通对象结构恢复，因此序列化时保存 dataType:Map 和 entries，反序列化器再重建 Map。解析失败时退回空名称集合，避免一份损坏名称记录阻止整个页面打开。

加载与保存要求飞机供电。前端可见条件来自 AC 1 供电变量，真正的灯光状态仍由运行环境处理。名称修改成功不能作为灯光参数已经成功保存的证明。''',diagram=D('entity','灯光名称与实际预设分别管理',[['前端名称','presetID → name','LIGHT_PRESET_NAMES','Map 序列化'],['编号槽位','1～8','加载 / 保存入口','供电许可'],['运行环境','灯光通道状态','按编号保存','按编号恢复']],[(0,1,'提供可读名称'),(1,2,'按固定编号操作')]),table=T('数据|保存位置含义|内容','名称映射|前端持久设置|编号及文字\n灯光快照|原生运行后端|实际通道值\n供电状态|宿主变量|是否允许操作\n槽位编号|前后台协议|稳定关联键')),
P('自动灯光选择与模块分工','''自动加载配置分别保存白天、晨昏和夜间的预设编号，零表示不选择。下拉选项由已有名称映射生成，便于使用者识别槽位。改名影响显示文字，不改变同一编号所指向的后台预设。

飞机预设和灯光预设共用“编号请求—后台处理”的思想，但作用范围不同。前者应用整机程序，后者针对灯光状态，二者不应共用一个模糊的“配置已保存”消息。

本地浏览器能够展示名称、选择项和页面交互。若后续接入其他仿真宿主，需要分别确认整机预设与灯光快照能力，而不是把单个开关接口扩大解释为完整预设系统。''',diagram=D('tree','自动灯光选择的三类时段',['自动灯光预设',['白天','DAY 编号','0 = 不选择'],['晨昏','DAWNDUSK 编号','0 = 不选择'],['夜间','NIGHT 编号','0 = 不选择']]),table=T('模块|请求身份|后端责任','飞机预设|1～5 的程序编号|执行系统程序\n灯光预设|1～8 的槽位编号|存取灯光状态\n自动灯光选择|各时段的槽位引用|按运行条件应用')) ,refs=['EFB','L-H'])

c=C(15,'设置、外部服务与运行配置详细设计','第二篇  分模块详细设计')
S(c,'设置模型与持久化',
P('设置导航的专业分组','''Settings 将配置组织为 Aircraft Options / Pin Programs、Sim Options、Realism、3rd Party Options、ATSU / AOC、Audio、flyPad 和 About 八个入口。SettingsPage 提供统一标题、返回入口和滚动容器，专业页面只组织自己的配置内容。

SettingItem 显示名称和控件，SettingGroup 表示父子依赖，disabled 控制暂不可操作的内容。某些选项带有 Unrealistic 提示，说明它们是便于仿真操作的便利设置，而不是飞机真实构型说明。

这种分组让显示偏好、飞机选装和外部服务凭据各有位置。它们不会全部写入 Flight，因为航班业务对象不应承担整个应用的设备配置。''',diagram=D('tree','设置模块的职责分组',['Settings',['飞机与仿真','Aircraft / Sim','Realism'],['服务与音频','3rd Party / ATSU','Audio'],['平板与身份','flyPad','About']]),table=T('配置类别|典型内容|生命周期','显示偏好|主题、语言、时间格式|随用户设备保存\n飞机选项|单位、选装参数|随机型配置使用\n外部服务|提供者及连接信息|随服务环境变化\n应用身份|版本与构建信息|随发布版本变化')),
P('类型化设置和历史键','''源码同时使用 usePersistentSetting 与 usePersistentProperty 等接口。前者面向类型化设置定义，后者保留字符串或数字形式的历史键。sync.ts 用判别字段 type 区分 setting 与 legacy 两类同步描述。

同步描述至少包含设置键和目标 LVar 名称，可选变量单位、默认值和 mapFunction。默认映射使用 Number，但布尔或枚举语义可能需要显式转换。把字符串直接写成 Number 并不适用于所有设置。

这一层将界面保存值与运行环境变量分开。用户改动主题只影响 UI；某些音量和模型选项则需要同步到宿主，才能被其他系统消费。''',diagram=D('entity','设置定义到宿主同步描述',[['持久设置','settingKey 或 configKey','默认值','类型化或 legacy'],['同步描述','localVarName','localVarUnit','mapFunction'],['宿主变量','转换后的值','运行消费者','后续状态读取']],[(0,1,'按定义读取'),(1,2,'转换后写入')]),table=T('属性|含义|设计作用','type|setting / legacy|选择读取方式\nlocalVarName|带 L: 的目标|明确宿主接口\nlocalVarUnit|写入单位|维持类型语义\nmapFunction|可选转换|枚举及布尔映射')),
P('本地默认值与用户保存值','''浏览器适配层只在设置键不存在时写入默认值，包括中文界面、固定亮度、关闭电池寿命演示和关闭 SimBridge 自动连接。已有用户设置不会在每次页面加载时无条件被覆盖。

因此首次运行和已经使用过的浏览器可能显示不同主题或选项。运行手册应以界面当前状态为准，不把某张截图中的开关位置认定为所有机器固定一致。

localStorage 按浏览器来源隔离。更换主机名、端口或浏览器配置文件，可能进入另一套保存空间。127.0.0.1 和 localhost 即使指向同一机器，也不是同一个网页来源。''',diagram=D('state','设置默认值的写入条件',['读取设置键','键不存在','已有用户值','写入本地默认','按当前值运行'],[(0,1,'首次使用'),(0,2,'已有记录'),(1,3,'初始化'),(2,4,'保留'),(3,4,'继续加载')]),table=T('变化|保存空间关系|用户感受','刷新同一地址|相同来源|设置通常保留\n改用 localhost|不同主机来源|可能看到默认值\n更换端口|不同来源|可能看到默认值\n更换浏览器配置|独立存储|需要重新设置')) ,refs=['EFB','L-H','SET'])
S(c,'显示、仿真与音频设置',
P('平板显示偏好','''flyPad 页面提供亮度、自动亮度、主题、语言、键盘布局、时间显示和时间格式等设置。它们共同影响阅读体验，但输入数据的内部单位和数值不应随主题或语言改变。

时间显示选择 UTC 或本地时间，格式选择 12 或 24 小时。航班数据中的 ISO 时间和保存的日期仍保持自身约定；仅改变显示格式不会重排航班日期或重新计算计划航程。

本地启动修复保持逻辑画布 1430×1000 并适配窗口。显示设置中的亮度与宿主整体缩放是两件事：前者改变视觉明暗，后者决定全部控件的实际屏幕尺寸。''',diagram=D('components','显示偏好对页面的作用范围',['语言与键盘','主题与亮度','时间偏好','共享显示组件','业务输入对象'],[(0,3,'文字与输入体验'),(1,3,'颜色和明暗'),(2,3,'时间格式'),(4,3,'数值内容')]),table=T('选项|影响内容|不改变的业务语义','语言|标签与提示|Flight 字段结构\n主题|色彩|计算数值\n时间格式|时间表达|保存时间身份\n亮度|视觉强度|结果有效状态')),
P('真实性与操作便利参数','''Realism 提供对准时间、显示器自检时间、登机速度、检查单自动填写和若干仿真便利选项。它们改变运行过程或交互方式，有些需要后端系统实际读取对应变量才能产生效果。

检查单自动填写在当前前端具有明确可见影响：带条件条目由变量判断控制。登机速度则同时影响时间估计和运行过程配置。两者都位于 Realism，但处理层并不相同。

操作说明应说明改动后观察什么页面，而不是笼统地说“参数设置成功，飞机已生效”。在浏览器开发宿主里，保存设置与真实仿真行为完成之间存在明确边界。''',diagram=D('lanes','同类设置可能由不同层消费',[['前端消费','自动检查单','条目判断方式','页面直接变化'],['后端消费','对准 / 自检时间','系统运行参数','宿主执行'],['联合消费','登机速度','估计与过程参数','界面及宿主协同']]),table=T('配置|主要消费者|当前理解','EFB_AUTOFILL_CHECKLISTS|检查单前端|控制条件项交互\nCONFIG_BOARDING_RATE|载重页及运行模块|过程速度配置\nCONFIG_ALIGN_TIME|飞机运行系统|对准时长配置\nCONFIG_SELF_TEST_TIME|显示器运行系统|自检时长配置')),
P('音量分组与模型选项','''Audio 将外部总音量、发动机、风声和客舱音频分别组织，客舱部分又包括旅客环境声、广播和登机音乐。声音参数以独立持久键保存，可以通过同步描述写入相应 LVar。

飞机选项中包括质量显示单位、部分高度参数、仪表单位和外观配置。参数属于机型可配置项，不应混入每一次性能计算输入而造成相同含义多处保存。

浏览器运行没有原生飞机音频和三维模型系统。滑块和开关的保存可用性与最终声音、模型变化分开说明，能减少用户误把依赖缺失当作按钮故障。''',diagram=D('tree','音频设置的分组结构',['音频参数',['驾驶舱与外部','外部总量','发动机与风'],['客舱','旅客环境声','广播与音乐'],['传递路径','持久设置','宿主声音变量']]),table=T('配置域|存储方式|最终消费层','音量数值|持久数字设置|原生声音系统\n客舱音频开关|持久布尔或数字|原生声音系统\n质量显示单位|类型化设置|页面格式化\n模型选装|持久设置及同步|三维模型系统')) ,refs=['EFB','L-H','SET'])
S(c,'外部服务与能力隔离',
P('天气与通信服务选择','''ATSU / AOC 页面分别保存 ATIS、METAR、TAF 数据源，以及 ACARS 提供者和相关连接参数。不同资料类型有各自服务选择，不能把一次 METAR 成功请求等同于所有通信功能已经可用。

CONFIG_METAR_SRC 的原生默认值为 MSFS，本地宿主的 GET_METAR_BY_IDENT 返回空报文。用户在仪表盘看到无天气内容时，可以据此理解为没有真实天气供给，而非本地航班未保存。

Flight.weather 是手工输入的计算条件，不会因为仪表盘刷新天气就自动被改写。保持这种隔离，能避免在线天气更新悄悄改变已确认的参考计算输入。''',diagram=D('lanes','在线天气显示与计算输入保持独立',[['天气显示','服务选择','报文读取','仪表盘解析'],['计算条件','用户手工录入','Flight.weather','确认后计算']]),table=T('数据|当前来源|与本地计算的关系','METAR 展示|配置的服务|不自动覆盖输入\nATIS / TAF|各自服务|独立资料入口\nFlight.weather|手工航班字段|明确进入计算\nACARS 状态|通信运行环境|不属于天气数值')),
P('第三方集成的配置条件','''第三方选项负责 SimBridge、GSX 等集成配置。选择启用表示用户允许或要求使用某类接口，不意味着对应程序已经安装、运行并连接。连接状态仍需从实际客户端或宿主变量取得。

GSX 燃油与载荷同步会改变地面页面的许可条件和过程控制。SimBridge 为本地文件与其他扩展提供服务连接。这些依赖有不同职责，不能用“第三方已开启”作为统一成功状态。

本交付默认核心离线航班流程独立运行，外部服务界面按其真实未连接状态展示。操作书不会要求用户创建 SimBrief 航班来完成本地工作台的核心流程。''',diagram=D('components','外部集成配置与连接能力',['集成设置','SimBridge 客户端','GSX 状态变量','资料及地面页面','本地航班流程'],[(0,1,'配置连接'),(0,2,'配置同步'),(1,3,'文件等服务'),(2,3,'地面过程信息'),(4,3,'提供本地计划')]),table=T('外部系统|主要作用|本地核心流程是否依赖','SimBridge|本地资料等服务|否\nGSX|机场地服协同|否\nNavigraph|授权航图|否\nSimBrief|在线航班计划|本流程不使用')),
P('凭据与本地文件出口','''通信设置中的账户标识和密钥属于连接配置，不属于航班计划 JSON。用户导出 Flight 时应只包含业务字段；报告使用输入快照和模型版本，不需要把服务凭据一并写入文档。

浏览器持久存储便于本机恢复，但并不是加密凭据保险库。当前本地演示没有配置真实服务账号，因此操作截图和交付资料中也不应出现虚构有效账号或真实密钥。

以后若增加组织级服务，应把认证和令牌生命周期放在专门模块，使用最小必要的前端状态表达连接身份。不能让每个业务页面自行保存一份访问令牌，增加失效与泄漏风险。''',diagram=D('entity','业务文件与连接凭据分开管理',[['航班文件','身份与机场','载荷 / 燃油','跑道 / 天气'],['服务配置','提供者','账户标识','认证状态'],['结果报告','输入快照','结果及版本','来源说明']],[(0,2,'报告使用业务输入')]),table=T('数据|航班 JSON|参考报告','航班号与机场|包含|包含\n重量与环境|包含|包含\n资料版本|机型身份部分|包含计算版本\n服务密钥|不包含|不包含')),
P('版本身份与 About 页面','''About 提供机型和应用身份等信息，适合核对当前运行基线。浏览器外壳的健康接口进一步给出应用名、browser-development 模式和 Headwind 固定提交。这些信息共同说明运行的是哪一套软件。

界面版本、源码提交、参考资料版本和内核版本不是同一个编号。修改页面样式不一定改变计算内核，修订速度资料也不一定改变上游源码提交。因此报告和交付说明分别记录这些身份。

书中的源码分析固定到所列提交，网上文档可能继续更新。遇到差异时，应先确认当前构建和文档版本，而不是用最新网页截图直接推断本地固定版本已有相同功能。''',diagram=D('entity','运行与计算的多层版本身份',[['软件基线','Headwind commit','FlyByWire commit','本地构建产物'],['计算基线','profileId','profileVersion','engineVersion'],['运行身份','application','mode','健康接口']],[(0,2,'形成当前运行'),(1,2,'当前计算资料')]),table=T('身份|定位的问题|保存位置','源码提交|代码来自哪里|BASELINE 与健康信息\n资料版本|使用哪套表格|Result / profile\n内核版本|采用哪版算法|Result / profile\n模式|运行在哪种宿主|健康接口与外壳')) ,refs=['EFB','L-H','L-D','SET'])
